 "shared_status_map": {"all_home": "home", "some_hospital": "hospital", "split_time": "both", "not_with_me": "not_with_me", "loss": "deceased", "complicated": "unknown"}, "child_status_from": "PST_CHILD_STATUS_BY_CHILD", "child_names_from": "PST_CHILD_REFERENCE", "options": ["one_baby", "twins", "triplets", "more_than_three", "prefer_not_to_say"], "option_labels": {"one_baby": "One baby", "twins": "Twins", "triplets": "Triplets", "more_than_three": "More than three", "prefer_not_to_say": "Prefer not to answer"}, "required": true, "label": "How many babies were born?"}, {"field_id": "PST_CHILD_STATUS", "format": "single_choice", "profile_path": "postpartum.child_status_shared", "options": ["all_home", "some_hospital", "split_time", "not_with_me", "loss", "complicated", "prefer_not_to_say"], "option_labels": {"all_home": "My baby or all of my babies are home with me", "some_hospital": "One or more babies are still in the hospital or NICU", "split_time": "I split my time between home and the hospital", "not_with_me": "My baby or babies are not with me for another reason", "loss": "The birth ended in the loss of my baby or babies", "complicated": "My situation is complicated and I would rather not describe it", "prefer_not_to_say": "Prefer not to answer"}, "required": true, "label": "Which option best describes your situation right now?"}, {"field_id": "PST_CHILD_COUNT_EXACT", "format": "number", "profile_path": "postpartum.children_exact", "required": false, "skippable": true, "show_if": {"field_id": "PST_MULTIPLES", "in": ["more_than_three"]}, "min": 4, "max": 8, "label": "How many babies exactly were born?"}, {"field_id": "PST_CHILD_REFERENCE", "format": "per_child_short_text", "profile_path": "postpartum.child_names", "required": false, "skippable": true, "max_length": 50, "show_if": {"all": [{"field_id": "PST_MULTIPLES", "not_in": ["one_baby"]}, {"field_id": "PST_CHILD_STATUS", "not_in": ["loss"]}]}, "repeat_count_from": "PST_MULTIPLES", "repeat_count_map": {"one_baby": 1, "twins": 2, "triplets": 3}, "repeat_count_exact_from": "PST_CHILD_COUNT_EXACT", "label": "What should we call each baby in the app?", "hint": "Use a name, a nickname, or anything that feels right. You can leave this empty — Momna will say \"your first baby\" and \"your second baby.\""}, {"field_id": "PST_CHILD_STATUS_BY_CHILD", "format": "per_child_single_choice", "profile_path": "postpartum.child_status_by_child", "required": false, "skippable": true, "show_if": {"all": [{"field_id": "PST_MULTIPLES", "not_in": ["one_baby"]}, {"field_id": "PST_CHILD_STATUS", "not_in": ["all_home"]}]}, "repeat_count_from": "PST_MULTIPLES", "repeat_count_map": {"one_baby": 1, "twins": 2, "triplets": 3}, "repeat_count_exact_from": "PST_CHILD_COUNT_EXACT", "options": ["home", "hospital", "both", "not_with_me", "deceased", "prefer_not_to_say"], "option_labels": {"home": "At home with me", "hospital": "In the hospital", "both": "Going back and forth between home and the hospital", "not_with_me": "Not with me for another reason", "deceased": "This baby did not survive", "prefer_not_to_say": "Prefer not to answer"}, "label": "Where is each baby right now?"}, {"field_id": "PST_MIXED_LOSS_SUPPORT", "format": "multi_choice", "profile_path": "postpartum.mixed_loss_support", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "show_if": {"all": [{"field_id": "PST_CHILD_STATUS_BY_CHILD", "by_child_any_in": ["deceased"]}, {"field_id": "PST_CHILD_STATUS_BY_CHILD", "by_child_any_in": ["home", "hospital", "both", "not_with_me"]}]}, "options": ["remember_baby", "hard_reminders", "care_support", "grief_support", "no_one_decide", "dont_know_yet", "prefer_not_to_say"], "option_labels": {"remember_baby": "It matters to me that Momna remembers the baby I lost", "hard_reminders": "Reminders about the loss are hard for me right now", "care_support": "I need support with caring for the baby who is with me", "grief_support": "I need support with what I am going through", "no