ined": "It was not clearly explained to me", "prefer_not_to_say": "Prefer not to answer"}, "label": "Did your care team ask you to keep any birth complications in mind during recovery?"}, {"field_id": "PST_CURRENT_CARE", "format": "multi_choice", "profile_path": "postpartum.current_care", "sensitivity_level": "health", "required": false, "skippable": true, "options": ["monitor_bp", "monitor_bloodwork", "incision_care", "movement_limits", "hospital_visits", "prescribed_meds", "none", "still_in_hospital", "prefer_not_to_say"], "option_labels": {"monitor_bp": "I need to monitor my blood pressure", "monitor_bloodwork": "I need follow-up bloodwork or anemia monitoring", "incision_care": "I am caring for an incision, wound, or stitches", "movement_limits": "I have movement or lifting restrictions", "hospital_visits": "I need regular hospital or clinic visits", "prescribed_meds": "I take prescribed medication", "none": "None of these", "still_in_hospital": "I am still in the hospital", "prefer_not_to_say": "Prefer not to answer"}, "label": "Are you still following any medical instructions or monitoring after discharge?"}, {"field_id": "PST_PHYSICAL", "format": "multi_choice", "max_select": 5, "profile_path": "postpartum.physical", "sensitivity_level": "health", "options": ["pain_after_birth", "incision", "bleeding", "weakness_dizziness", "back_pelvic_joint_pain", "urinary_leakage", "pelvic_pressure", "constipation", "swelling", "headaches", "nothing_much", "something_else"], "option_labels": {"pain_after_birth": "Pain after birth", "incision": "Stitches or a C-section incision", "bleeding": "Postpartum bleeding", "weakness_dizziness": "Severe weakness or dizziness", "back_pelvic_joint_pain": "Back, pelvic, hip, or joint pain", "urinary_leakage": "Urinary leakage", "pelvic_pressure": "Pelvic pressure or heaviness", "constipation": "Constipation or pain with bowel movements", "swelling": "Swelling", "headaches": "Headaches", "nothing_much": "Nothing is bothering me much", "s