ies": "Caring for more than one baby", "housework": "Housework", "older_children_family": "Caring for older children or family members", "not_enough_help": "Not having enough help", "anxiety": "Anxiety or constant worrying", "grief": "Grief after a loss", "something_else": "Something else"}, "required": true, "label": "What is taking the most out of you right now?"}, {"field_id": "PST_WORK", "format": "single_choice", "profile_path": "postpartum.work", "required": false, "skippable": true, "options": ["on_leave", "need_return_soon", "from_home", "in_person", "shifts", "not_working", "prefer_not_to_say"], "option_labels": {"on_leave": "I am on leave and not planning to return yet", "need_return_soon": "I need to return soon", "from_home": "I am already working or studying from home", "in_person": "I am already returning in person", "shifts": "I work shifts", "not_working": "I am not currently working or studying", "prefer_not_to_say": "Prefer not to answer"}, "label": "What is happening with work or school right now?"}, {"field_id": "PST_MENTAL", "format": "multi_choice", "max_select": 3, "profile_path": "person.emotional_baseline", "sensitivity_level": "health", "options": ["mostly_coping", "exhausted_overwhelmed", "anxious", "cry_sad", "irritable_angry", "disconnected", "emotions_change_fast", "guilt_not_enough", "grief", "hard_to_tell", "prefer_not_to_say"], "option_labels": {"mostly_coping": "I am mostly coping", "exhausted_overwhelmed": "I feel exhausted and overwhelmed", "anxious": "I feel anxious a lot", "cry_sad": "I cry often or feel deeply sad", "irritable_angry": "I feel irritable or angry", "disconnected": "I feel disconnected or numb", "emotions_change_fast": "My emotions change very quickly", "guilt_not_enough": "I feel guilty that I am not doing enough", "grief": "I am grieving after a loss", "hard_to_tell": "It is hard for me to tell", "prefer_not_to_say": "Prefer not to answer"}, "required": true, "label": "Which feelings have been most common over t