ically": "My partner is currently unable to help physically", "hard_to_ask": "It is hard for me to ask for specific help", "tension": "There is a lot of tension between us", "pressured_unsafe": "I feel pressured or unsafe", "prefer_not_to_say": "Prefer not to answer"}, "label": "How are baby-care responsibilities divided right now?"}, {"field_id": "PST_INTIMACY_STATUS", "format": "single_choice", "profile_path": "postpartum.intimacy_status", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "options": ["yes_regularly", "sometimes", "not_yet_comfortable", "not_yet_worried", "medical_restriction", "not_applicable", "prefer_not_to_say"], "option_labels": {"yes_regularly": "Yes, regularly", "sometimes": "Sometimes", "not_yet_comfortable": "Not yet, and I am comfortable with that", "not_yet_worried": "Not yet, and it worries me", "medical_restriction": "I have a medical restriction", "not_applicable": "This question does not apply to my situation", "prefer_not_to_say": "Prefer not to answer"}, "label": "Has sexual activity resumed since the birth?"}, {"field_id": "PST_INTIMACY_COMFORT", "format": "multi_choice", "profile_path": "postpartum.intimacy_comfort", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "show_if": {"field_id": "PST_INTIMACY_STATUS", "in": ["yes_regularly", "sometimes", "not_yet_worried"]}, "options": ["comfortable", "desire_decreased", "dryness_pain", "fear_pregnancy", "body_discomfort", "partner_pressure", "want_affection_no_sex", "hard_to_talk", "prefer_not_to_say"], "option_labels": {"comfortable": "I am comfortable with things as they are", "desire_decreased": "My desire has decreased", "dryness_pain": "I have dryness, pain, or fear of pain", "fear_pregnancy": "I am worried about becoming pregnant again", "body_discomfort": "I do not feel comfortable in my body", "partner_pressure": "My partner is rushing or pressuring me", "want_affection_no_sex": "I want affection without sex", "hard_to_