tions": ["clear_plan", "flexible_suggestions"], "option_labels": {"clear_plan": "Clear plan", "flexible_suggestions": "Flexible suggestions"}}, {"row_id": "depth", "options": ["action_first", "explain_first"], "option_labels": {"action_first": "Give me the action first", "explain_first": "Explain it first"}}, {"row_id": "reminders", "options": ["gentle_reminders", "only_important_alerts"], "option_labels": {"gentle_reminders": "Gentle reminders", "only_important_alerts": "Only important alerts"}}, {"row_id": "checkins", "options": ["check_in_often", "dont_interrupt"], "option_labels": {"check_in_often": "Check in often", "dont_interrupt": "Do not interrupt unless needed"}}], "required": true, "label": "How do you prefer to receive support?"}, {"field_id": "PST_TONE", "format": "single_choice", "profile_path": "person.communication.tone", "options": ["gentle", "friendly", "close_friend", "direct"], "option_labels": {"gentle": "Gentle - soft and careful, with no jokes", "friendly": "Friendly - natural and easy, with occasional light humor", "close_friend": "Like someone who knows me well - informal, conversational, and okay with jokes", "direct": "Direct - brief, honest, and never overly sweet"}, "required": true, "label": "How can Momna talk with you?"}]}]}'::jsonb, 'draft')
on conflict (onboarding_key, version, locale) do update
  set schema = excluded.schema, status = 'draft';

update public.onboarding_definitions
set status = 'archived'
where onboarding_key = 'postpartum' and version = 1;

do $$
declare v_id uuid;
begin
  for v_id in
    select id from public.onboarding_definitions
    where onboarding_key = 'postpartum' and version = 2
  loop
    perform public.publish_onboarding_definition(v_id);
  end loop;
end $$;